import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getOneWorkout } from '../@services/workouts.service';
import { IWorkoutFull } from '../@types/workouts.types';
import WorkoutMarkupEdit from '../components/WorkoutMarkupEdit';

const WorkoutMarkupPage: React.FC<{ id_workout: number }> = ({ id_workout }) => {
  const [data, setData] = React.useState<IWorkoutFull | null>(null);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const fetchData = async () => {
      const d = await getOneWorkout(id_workout);
      setData(d);
    };

    fetchData().catch(setErr);
  }, [id_workout]);

  if (!data) {
    return <PageLoader />;
  }

  if (err) return <PohAlert>{err.message}</PohAlert>;

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/${id_workout}`, text: data.name },
            { href: `/workouts/${id_workout}/markup`, text: 'Разметка трека', active: true },
          ]}
        />
        <PohContainer>
          <PohRow>
            <PohCol sm={12}>
              <WorkoutMarkupEdit workout={data} />
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutMarkupPage;
